namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra cheese.",
            AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nHeavy cream\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger in oil.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.",
            AverageRating = 4.6, RatingCount = 15
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nGarlic\nEggs",
            Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, then pan-fry until golden.\n3. Scramble eggs in the same pan.\n4. Mix tamarind paste, fish sauce, and sugar for sauce.\n5. Stir-fry noodles with sauce, tofu, and eggs.\n6. Serve with bean sprouts, peanuts, and lime.",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco shells\nLettuce\nTomatoes\nCheddar cheese\nSour cream\nTaco seasoning",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm taco shells in oven.\n4. Fill shells with seasoned beef.\n5. Top with lettuce, tomatoes, cheese, and sour cream.",
            AverageRating = 4.0, RatingCount = 10
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve and pit avocados.\n2. Mash avocado flesh in a bowl.\n3. Dice onion, tomato, and jalapeño.\n4. Mix all ingredients together.\n5. Season with salt and lime juice.\n6. Serve immediately with tortilla chips.",
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 7, Title = "Miso Ramen", Category = "Asian",
            Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoft-boiled eggs\nChashu pork\nGreen onions\nNori\nCorn",
            Steps = "1. Simmer chicken broth with miso paste.\n2. Cook ramen noodles according to package.\n3. Slice chashu pork thinly.\n4. Prepare soft-boiled eggs (6.5 minutes).\n5. Assemble bowls with noodles and broth.\n6. Top with pork, egg, nori, corn, and green onions.",
            AverageRating = 4.9, RatingCount = 25
        },
        new Recipe
        {
            Id = 8, Title = "Palak Paneer", Category = "Indian",
            Ingredients = "Paneer\nSpinach\nOnion\nGarlic\nGinger\nGreen chilies\nCream\nCumin seeds",
            Steps = "1. Blanch spinach and blend into a puree.\n2. Cube paneer and lightly fry until golden.\n3. Sauté cumin, onion, garlic, and ginger.\n4. Add spinach puree and simmer.\n5. Stir in cream and add paneer cubes.\n6. Season with salt and serve with naan.",
            AverageRating = 4.4, RatingCount = 11
        }
    };

    private readonly Dictionary<(int recipeId, string visitorId), int> _ratings = new();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void RateRecipe(int recipeId, int stars, string visitorId)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        var key = (recipeId, visitorId);
        if (_ratings.ContainsKey(key))
        {
            var oldRating = _ratings[key];
            var totalStars = recipe.AverageRating * recipe.RatingCount - oldRating + stars;
            recipe.AverageRating = totalStars / recipe.RatingCount;
        }
        else
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = totalStars / recipe.RatingCount;
        }
        _ratings[key] = stars;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

