@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe")</PageTitle>

<div class="container">
    @if (Recipe == null)
    {
        <p class="text-danger">Recipe not found.</p>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            </ol>
        </nav>

        <h1>@Recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@Recipe.Category</span>

        <div class="mb-4">
            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
        </div>

        <div class="row">
            <div class="col-md-4">
                <div class="card mb-3">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@rendermode InteractiveServer

@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <h1>Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <strong>Thank you!</strong> Your recipe "<strong>@Title</strong>" has been submitted successfully.
            <a href="/recipe/@SubmittedId">View it here</a>.
        </div>
    }
    else
    {
        <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="SelectedCategory" class="form-select">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Asian">Asian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="American">American</option>
                    <option value="French">French</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" @bind-Value="Ingredients" class="form-control" rows="5"
                    placeholder="One ingredient per line" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" @bind-Value="Steps" class="form-control" rows="6"
                    placeholder="Describe each step on a new line" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@(!IsFormValid)">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private string Title { get; set; } = string.Empty;
    private string SelectedCategory { get; set; } = string.Empty;
    private string Ingredients { get; set; } = string.Empty;
    private string Steps { get; set; } = string.Empty;
    private bool Submitted { get; set; }
    private int SubmittedId { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(Title) &&
        !string.IsNullOrWhiteSpace(SelectedCategory) &&
        !string.IsNullOrWhiteSpace(Ingredients) &&
        !string.IsNullOrWhiteSpace(Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;

        var recipe = new Recipe
        {
            Title = Title,
            Category = SelectedCategory,
            Ingredients = Ingredients,
            Steps = Steps
        };

        RecipeService.AddRecipe(recipe);
        SubmittedId = recipe.Id;
        Submitted = true;
    }
}

@using RecipeCommunity.Services

@inject RecipeService RecipeService

<div class="d-inline-block">
    <span class="me-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" class="fs-4" style="cursor: pointer; color: @(star <= SelectedRating ? "#ffc107" : "#dee2e6")"
                @onclick="() => Rate(star)"
                @onmouseover="() => HoverRating = star"
                @onmouseout="() => HoverRating = 0">
                @(star <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "★" : "☆")
            </span>
        }
    </span>
    @if (SelectedRating > 0)
    {
        <small class="text-muted">You rated this @SelectedRating/5</small>
    }
    else
    {
        <small class="text-muted">Click to rate</small>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private int HoverRating { get; set; }
    private string VisitorId { get; set; } = Guid.NewGuid().ToString();

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.RateRecipe(RecipeId, stars, VisitorId);
    }
}

